CREATE TABLE `Customer` (
  `CustId` int(11) NOT NULL AUTO_INCREMENT,
  `SiteId` int(11) NOT NULL DEFAULT '1',
  `UserName` varchar(30) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `Userpwd` varchar(50) NOT NULL,
  `CurrencyId` tinyint(4) NOT NULL,
  `UserLang` varchar(4) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL DEFAULT 'en',
  `ActStatus` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1: Non-Depoist, 2: has Depoist',
  `AgentId` int(11) NOT NULL,
  `AllAgentId` json DEFAULT NULL,
  `UserLevel` tinyint(4) NOT NULL DEFAULT '1',
  `LastLoginTime` datetime DEFAULT NULL,
  `RegTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `IsTest` tinyint(1) NOT NULL DEFAULT '0',
  `IsKyc` tinyint(1) NOT NULL DEFAULT '0',
  `IsRisk` tinyint(1) NOT NULL DEFAULT '0',
  `Status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '1: Running, 2: Suspend, 3: Closed',
  PRIMARY KEY (`CustId`),
  UNIQUE KEY `CustomerIdx1` (`UserName`)
) ENGINE=InnoDB AUTO_INCREMENT=231 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
